import {
    Table,
    JsonColumn,
    StringColumn,
    IntegerColumn,
    DateTimeColumn,
    ChoiceColumn,
    TableNameColumn,
    BooleanColumn,
    GuidColumn,
    DomainPathColumn,
    ReferenceColumn,
    DomainIdColumn,
    DocumentIdColumn,
} from '@servicenow/sdk/core'

export const sys_flow_context = Table({
    allowWebServiceAccess: true,
    attributes: {
        forcePrimaryKeyOrdering: true,
        iterativeDelete: false,
        native_recordlock: true,
        no_audit_delete: true,
        update_synch: false,
    },
    label: 'Flow engine context',
    name: 'sys_flow_context',
    schema: {
        attributes: JsonColumn({
            attributes: {
                json_view: true,
            },
            label: 'Attributes',
            readOnly: true,
        }),
        flow: StringColumn({
            label: 'Flow',
            maxLength: 32,
            readOnly: true,
        }),
        engine_version: IntegerColumn({
            label: 'Last Executed Release',
            maxLength: 10,
            readOnly: true,
        }),
        sys_lock_touched: DateTimeColumn({
            label: 'Conversation Lock Touched',
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                    language: 'en',
                },
            ],
        }),
        state: ChoiceColumn({
            dropdown: 'dropdown_with_none',
            label: 'State',
            readOnly: true,
        }),
        source_table: TableNameColumn({
            attributes: {
                base_start: true,
            },
            label: 'Source Table',
            readOnly: true,
        }),
        snapshot: StringColumn({
            label: 'Snapshot',
            maxLength: 32,
            readOnly: true,
        }),
        error_state: ChoiceColumn({
            dropdown: 'dropdown_with_none',
            label: 'Error State',
            readOnly: true,
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                    language: 'en',
                },
            ],
        }),
        is_test_run: BooleanColumn({
            label: 'Is test run',
            readOnly: true,
        }),
        calling_source: StringColumn({
            label: 'Calling Source',
            readOnly: true,
        }),
        transaction: StringColumn({
            label: 'Transaction',
            maxLength: 32,
            readOnly: true,
        }),
        plan: JsonColumn({
            attributes: {
                json_view: true,
            },
            label: 'Plan',
            readOnly: true,
        }),
        application: StringColumn({
            label: 'Application',
            maxLength: 250,
            readOnly: true,
        }),
        reporting: StringColumn({
            default: 'ON',
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Turns ON/OFF the reporting during the flow execution',
                    label: 'Reporting',
                    plural: 'Reportings',
                    language: 'en',
                },
            ],
            readOnly: true,
        }),
        sys_lock_owner: StringColumn({
            label: 'Conversation Lock Owner',
            maxLength: 100,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
        name: StringColumn({
            label: 'Name',
            maxLength: 250,
            readOnly: true,
        }),
        origins: JsonColumn({
            attributes: {
                json_view: true,
            },
            label: 'Origins',
            maxLength: 8000,
            readOnly: true,
        }),
        skip_schedule_cleanup: BooleanColumn({
            default: false,
            label: 'Skip Schedule Cleanup',
        }),
        design_source: StringColumn({
            default: 'FLOW_DESIGNER',
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'The designer/builder that was the source of this execution',
                    label: 'Design Time Source',
                    plural: 'Design Time Sources',
                    language: 'en',
                },
            ],
            readOnly: true,
        }),
        signatures: JsonColumn({
            attributes: {
                json_view: true,
            },
            label: 'Signatures',
            maxLength: 10000,
            readOnly: true,
        }),
        execution_id: StringColumn({
            label: 'Execution ID',
            maxLength: 32,
            readOnly: true,
            unique: true,
        }),
        engine_major_version: IntegerColumn({
            label: 'Engine Major Version',
            maxLength: 2,
            readOnly: true,
        }),
        sys_lock_acquired: DateTimeColumn({
            label: 'Conversation Lock Acquired',
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                    language: 'en',
                },
            ],
        }),
        stages: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Stages',
            readOnly: true,
            referenceTable: 'stage_state',
        }),
        flow_catalog_model: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Flow catalog model',
            readOnly: true,
            referenceTable: 'sys_flow_cat_variable_model',
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the context belongs',
                    label: 'Domain',
                    plural: 'Domains',
                    language: 'en',
                },
            ],
        }),
        error_message: StringColumn({
            label: 'Error message',
            maxLength: 1000,
            readOnly: true,
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                    language: 'en',
                },
            ],
        }),
        run_time: IntegerColumn({
            label: 'Runtime',
            readOnly: true,
        }),
        source_record: DocumentIdColumn({
            dependent: 'source_table',
            label: [
                {
                    hint: 'The source script of this execution',
                    label: 'Source Record',
                    plural: 'Source Records',
                    language: 'en',
                },
            ],
            readOnly: true,
        }),
        claimed_by: StringColumn({
            label: 'Claimed by',
            maxLength: 250,
            readOnly: true,
        }),
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                    language: 'en',
                },
            ],
        }),
    },
})
